<main class="almsivi-page<?php echo $embedded?' embedded':''; ?>"><header class="almsivi-page-header"><div><h1>Playthrough Manager</h1><p>Versioned Morrowind playthrough scopes used by conversations, memories, relationships, and knowledge.</p></div><span class="almsivi-badge"><?php echo count($rows); ?> playthroughs</span></header><?php if(isset($_GET['status'])): ?><div class="almsivi-status">Playthrough operation completed.</div><?php endif; ?><section class="almsivi-card"><h2>Create playthrough</h2><form method="post" action="<?php echo almsivi_ui_h($managementBasePath); ?>/forms/playthroughs"><input type="hidden" name="_csrf" value="<?php echo almsivi_ui_h($csrf); ?>"><div class="almsivi-form-grid"><label>Installation<select name="installation_id"><?php foreach($installations as$row): ?><option value="<?php echo almsivi_ui_h($row['installation_id']); ?>"><?php echo almsivi_ui_h($row['display_name']); ?></option><?php endforeach; ?></select></label><label>Profile<select name="profile_id"><?php foreach($profiles as$row): ?><option value="<?php echo almsivi_ui_h($row['profile_id']); ?>"><?php echo almsivi_ui_h($row['name']); ?></option><?php endforeach; ?></select></label><label>Name<input name="name" required maxlength="256"></label><label class="wide">Playthrough JSON<textarea name="content_json" required>{}</textarea></label></div><div class="almsivi-actions"><button type="submit">Create Playthrough</button></div></form></section>
<section class="almsivi-card"><h2>Restore playthrough backup</h2><form method="post" action="<?php echo almsivi_ui_h($managementBasePath); ?>/forms/playthrough-import"><input type="hidden" name="_csrf" value="<?php echo almsivi_ui_h($csrf); ?>"><div class="almsivi-form-grid"><label>Installation<select name="installation_id"><?php foreach($installations as$row): ?><option value="<?php echo almsivi_ui_h($row['installation_id']); ?>"><?php echo almsivi_ui_h($row['display_name']); ?></option><?php endforeach; ?></select></label><label>Profile<select name="profile_id"><?php foreach($profiles as$row): ?><option value="<?php echo almsivi_ui_h($row['profile_id']); ?>"><?php echo almsivi_ui_h($row['name']); ?></option><?php endforeach; ?></select></label><label>Destination playthrough<select name="playthrough_id"><?php foreach($rows as$row): ?><option value="<?php echo almsivi_ui_h($row['playthrough_id']); ?>"><?php echo almsivi_ui_h($row['playthrough']); ?></option><?php endforeach; ?></select></label><label class="wide">ALMSIVI playthrough backup JSON<textarea name="playthrough_json" required></textarea></label></div><div class="almsivi-actions"><button type="submit">Restore Playthrough Backup</button></div></form></section>
